import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
/**
 * Asks before an action that changes the forum, in place of the browser's
 * `confirm()`: themed, translatable, and able to show what will change.
 */
export default class ConfirmModal extends Modal {
  className() {
    return 'Modal--small Millwright-confirm';
  }
  title() {
    return this.attrs.title;
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Millwright-confirm-message"
    }, this.attrs.message), this.attrs.details ? m("div", {
      className: "Millwright-confirm-details"
    }, this.attrs.details) : null, m("div", {
      className: "Millwright-confirm-actions"
    }, m(Button, {
      className: 'Button ' + (this.attrs.danger ? 'Button--danger' : 'Button--primary'),
      onclick: () => {
        this.hide();
        this.attrs.onconfirm();
      }
    }, this.attrs.confirmText), m(Button, {
      className: "Button",
      onclick: () => this.hide()
    }, app.translator.trans('ernestdefoe-millwright.admin.actions.cancel'))));
  }
  onready() {
    // The safe choice has focus, so Return does not confirm by accident.
    this.$('.Millwright-confirm-actions .Button:last-child').trigger('focus');
  }
}
flarum.reg.add('ernestdefoe-millwright', 'admin/components/ConfirmModal', ConfirmModal);